#pragma once
#include <juce_gui_basics/juce_gui_basics.h>

// The GLITCHKID logo system in the plug-in. The emblem (a forward-leaning GK whose K leg breaks out as a spike) and the wordmark are the exact
// outlines of Assets/Brand/*-white.svg (generated by tools/brand/gen_brand.py), compiled in and drawn as vector paths: sharp at every window size.
// The marks are brushed chrome; the current colour profile adds a fine accent edge. Drawing only.
namespace glitchkid::ui::brand
{
const juce::Path& emblem();     // in the SVG's own units; empty only if the asset is missing
const juce::Path& wordmark();
juce::Rectangle<float> fit (const juce::Path&, juce::Rectangle<float> area, juce::Justification); // where a mark lands inside an area (aspect kept)

void drawEmblem (juce::Graphics&, juce::Rectangle<float> area, juce::Justification = juce::Justification::centred, float alpha = 1.0f);
void drawWordmark (juce::Graphics&, juce::Rectangle<float> area, juce::Justification = juce::Justification::centredLeft, float alpha = 1.0f);
void drawTagline (juce::Graphics&, juce::Rectangle<float> area, float fontHeight); // "BUILT TO SOUND DIFFERENT", tracked out, fitted to the width

std::unique_ptr<juce::Drawable> appIcon(); // the square application icon (Assets/Brand/glitchkid-icon.svg)
constexpr const char* tagline = "BUILT TO SOUND DIFFERENT";
}
